<?php
session_start();require 'config/database.php';require 'lib_results.php';require 'lib_phase8.php';
if(!isset($_SESSION['user'])||$_SESSION['user']['role']!=='student'){header('Location: login.php');exit;}
$q=$pdo->prepare('SELECT st.*,u.name,u.email,p.level,p.name program_name,p.specialization FROM students st JOIN users u ON u.id=st.user_id JOIN programs p ON p.id=st.program_id WHERE st.user_id=?');$q->execute([$_SESSION['user']['id']]);$student=$q->fetch();if(!$student)exit('Student profile not found.');
$term=$student['semester_or_year'];$status=resultStatus($pdo,(int)$student['id'],$term);$result=studentResult($pdo,(int)$student['id'],$term);$overall=studentOverall($pdo,(int)$student['id']);
$showResult=in_array($status,['published','locked'],true);
$atts=attendanceSummary($pdo,(int)$student['id'],$term);
$aud=$pdo->quote(strtolower($student['level']));$n=$pdo->query("SELECT title,body,audience,published_at FROM notices WHERE audience='all' OR audience='students' OR audience=$aud ORDER BY published_at DESC LIMIT 6")->fetchAll();
$pageTitle='Student Portal';require 'includes/header.php';?>
