<div id="attendance" class="card shadow-sm border-0 mt-4"><div class="card-body"><h5 class="fw-bold">Attendance</h5><div class="table-responsive"><table class="table"><thead><tr><th>Subject</th><th>Present</th><th>Absent</th><th>Leave</th><th>Attendance</th><th>Status</th></tr></thead><tbody><?php foreach($atts as $r):$low=$r['total']>0&&$r['percentage']<75;?><tr><td><?=htmlspecialchars($r['code'].' — '.$r['name'])?></td><td><?=$r['present']?></td><td><?=$r['absent']?></td><td><?=$r['leave']?></td><td><?=number_format($r['percentage'],1)?>%</td><td><span class="badge text-bg-<?=$low?'danger':'success'?>"><?=$low?'Below 75%':'OK'?></span></td></tr><?php endforeach;if(!$atts):?><tr><td colspan="6" class="text-muted">No attendance records yet.</td></tr><?php endif;?></tbody></table></div><div class="small text-muted">Attendance warning threshold shown by the portal is 75%. Confirm the official institutional rule before production use.</div></div></div>
